import { Injectable } from '@angular/core';
import { CanActivate, Router, ActivatedRouteSnapshot } from '@angular/router';

@Injectable({ providedIn: 'root' })
export class StudentGuard implements CanActivate {
  constructor(private router: Router) {}

  canActivate(route: ActivatedRouteSnapshot): boolean {
    const accessData = localStorage.getItem('studentAccess');
    if (!accessData) {
      alert('⛔ Accès refusé : aucun code d’accès enregistré.');
      this.router.navigate(['/student/join']);
      return false;
    }

    const access = JSON.parse(accessData);
    const now = new Date().getTime();
    const routeId = route.params['id'];

    // ⏳ Vérifie si le token est expiré
    if (access.expiry < now) {
      alert('⏰ Votre session a expiré (4 heures max). Veuillez ressaisir le code.');
      localStorage.removeItem('studentAccess');
      this.router.navigate(['/student/join']);
      return false;
    }

    // 🔒 Vérifie si l’étudiant essaie d’accéder à une autre classe
    if (access.classId.toString() !== routeId) {
      alert('🚫 Vous n’avez pas accès à cette classe.');
      this.router.navigate(['/student/join']);
      return false;
    }

    return true;
  }
}
